//! Request routing and handlers for the kvhttp API.

use std::sync::Arc;

use axum::body::{Body, Bytes};
use axum::extract::{Request, State};
use axum::http::{Method, StatusCode, header};
use axum::response::{IntoResponse, Response};

use crate::store::{PutOutcome, Store};

/// Bodies are capped well above the 1 MiB value limit so oversized values are not cut mid-read.
pub const MAX_BODY_BYTES: usize = 8 * 1024 * 1024;

const KV_PREFIX: &str = "/kv/";

/// Returns true if `key` matches `[A-Za-z0-9_-]{1,64}`.
fn is_valid_key(key: &str) -> bool {
    (1..=64).contains(&key.len())
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

/// Entry point for every request: dispatches on the path, then on the method.
pub async fn handle(State(store): State<Arc<Store>>, req: Request) -> Response {
    let path = req.uri().path();
    if path == "/health" {
        return health(req.method());
    }
    if path == "/kv" {
        return list_keys(&store, req.method());
    }
    let Some(key) = path.strip_prefix(KV_PREFIX) else {
        return StatusCode::NOT_FOUND.into_response();
    };
    if !is_valid_key(key) {
        return StatusCode::BAD_REQUEST.into_response();
    }
    let key = key.to_owned();
    entry(&store, &key, req).await
}

fn health(method: &Method) -> Response {
    match *method {
        Method::GET => "ok".into_response(),
        _ => StatusCode::METHOD_NOT_ALLOWED.into_response(),
    }
}

fn list_keys(store: &Store, method: &Method) -> Response {
    if *method != Method::GET {
        return StatusCode::METHOD_NOT_ALLOWED.into_response();
    }
    let body = serde_json::to_vec(&store.keys()).expect("serializing strings cannot fail");
    ([(header::CONTENT_TYPE, "application/json")], body).into_response()
}

async fn entry(store: &Store, key: &str, req: Request) -> Response {
    match req.method().clone() {
        Method::GET => match store.get(key) {
            Some(value) => (
                [(header::CONTENT_TYPE, "application/octet-stream")],
                Body::from(value),
            )
                .into_response(),
            None => StatusCode::NOT_FOUND.into_response(),
        },
        Method::PUT => {
            let value = match read_body(req).await {
                Ok(value) => value,
                Err(response) => return response,
            };
            match store.put(key, value) {
                PutOutcome::Created => StatusCode::CREATED.into_response(),
                PutOutcome::Replaced => StatusCode::OK.into_response(),
            }
        }
        Method::DELETE => {
            if store.delete(key) {
                StatusCode::NO_CONTENT.into_response()
            } else {
                StatusCode::NOT_FOUND.into_response()
            }
        }
        _ => StatusCode::METHOD_NOT_ALLOWED.into_response(),
    }
}

async fn read_body(req: Request) -> Result<Bytes, Response> {
    axum::body::to_bytes(req.into_body(), MAX_BODY_BYTES)
        .await
        .map_err(|_| StatusCode::PAYLOAD_TOO_LARGE.into_response())
}

#[cfg(test)]
mod tests {
    use super::is_valid_key;

    #[test]
    fn key_validation() {
        assert!(is_valid_key("a"));
        assert!(is_valid_key("A-z_09"));
        assert!(is_valid_key(&"k".repeat(64)));
        assert!(!is_valid_key(""));
        assert!(!is_valid_key(&"k".repeat(65)));
        assert!(!is_valid_key("a/b"));
        assert!(!is_valid_key("bad.key"));
        assert!(!is_valid_key("é"));
    }
}

//! `app <port>` serves the kvhttp API on 127.0.0.1:<port>.

mod handler;
mod store;

use std::net::{Ipv4Addr, SocketAddr};
use std::process::ExitCode;
use std::sync::Arc;

use axum::Router;
use axum::extract::DefaultBodyLimit;

use crate::store::Store;

fn parse_port(arg: Option<String>) -> Option<u16> {
    arg?.parse().ok().filter(|&port| port != 0)
}

#[tokio::main]
async fn main() -> ExitCode {
    let Some(port) = parse_port(std::env::args().nth(1)) else {
        eprintln!("usage: app <port>");
        return ExitCode::from(2);
    };

    let app = Router::new()
        .fallback(handler::handle)
        .layer(DefaultBodyLimit::max(handler::MAX_BODY_BYTES))
        .with_state(Arc::new(Store::new()));

    let addr = SocketAddr::from((Ipv4Addr::LOCALHOST, port));
    let listener = match tokio::net::TcpListener::bind(addr).await {
        Ok(listener) => listener,
        Err(err) => {
            eprintln!("failed to bind {addr}: {err}");
            return ExitCode::FAILURE;
        }
    };

    if let Err(err) = axum::serve(listener, app).await {
        eprintln!("server error: {err}");
        return ExitCode::FAILURE;
    }
    ExitCode::SUCCESS
}

//! Thread-safe in-memory key-value store backed by a sorted map.

use std::collections::BTreeMap;
use std::sync::{PoisonError, RwLock};

use axum::body::Bytes;

/// Outcome of [`Store::put`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PutOutcome {
    Created,
    Replaced,
}

/// An in-memory map from keys to byte values, kept sorted by key.
#[derive(Debug, Default)]
pub struct Store {
    entries: RwLock<BTreeMap<String, Bytes>>,
}

impl Store {
    pub fn new() -> Self {
        Self::default()
    }

    /// Returns the value stored under `key`, if any.
    pub fn get(&self, key: &str) -> Option<Bytes> {
        self.read().get(key).cloned()
    }

    /// Stores `value` under `key`, reporting whether the key was new.
    pub fn put(&self, key: &str, value: Bytes) -> PutOutcome {
        match self.write().insert(key.to_owned(), value) {
            Some(_) => PutOutcome::Replaced,
            None => PutOutcome::Created,
        }
    }

    /// Removes `key`, returning whether it was present.
    pub fn delete(&self, key: &str) -> bool {
        self.write().remove(key).is_some()
    }

    /// Returns every key, sorted ascending.
    pub fn keys(&self) -> Vec<String> {
        self.read().keys().cloned().collect()
    }

    fn read(&self) -> std::sync::RwLockReadGuard<'_, BTreeMap<String, Bytes>> {
        self.entries.read().unwrap_or_else(PoisonError::into_inner)
    }

    fn write(&self) -> std::sync::RwLockWriteGuard<'_, BTreeMap<String, Bytes>> {
        self.entries.write().unwrap_or_else(PoisonError::into_inner)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn put_get_delete_list() {
        let store = Store::new();
        assert_eq!(store.put("b", Bytes::from_static(b"2")), PutOutcome::Created);
        assert_eq!(store.put("a", Bytes::from_static(b"1")), PutOutcome::Created);
        assert_eq!(store.put("a", Bytes::from_static(b"x")), PutOutcome::Replaced);
        assert_eq!(store.get("a").as_deref(), Some(&b"x"[..]));
        assert_eq!(store.keys(), ["a", "b"]);
        assert!(store.delete("a"));
        assert!(!store.delete("a"));
        assert_eq!(store.get("a"), None);
    }
}
